begin;
do $test$
declare
 actor uuid;ordinary uuid;tenant uuid;fund uuid;supplier uuid;supplier_two uuid;material uuid;unit_id uuid;finance_type uuid;payment_type uuid;purpose uuid;method uuid;fixture_role uuid;foreign_scheme uuid;foreign_tenant uuid;
 scheme_ident uuid;manual_scheme uuid;finance jsonb;payment jsonb;plan jsonb;result jsonb;item jsonb;blocked boolean;index_value integer;before_count bigint;
 original_rules jsonb;code_prefix text:='MATCH_'||upper(left(gen_random_uuid()::text,8));
begin
 select auth_user_id into actor from public.sys_user where auth_user_id is not null and user_roles @>array['R_SUPER'] limit 1;
 select f.tenant_id,f.id into tenant,fund from public.fms_fund_account f join public.fms_currency c on c.id=f.currency_id
 where f.status='active' and f.account_type<>'cash' and c.currency_code='CNY' and (select count(*) from public.mdm_supplier where tenant_id=f.tenant_id)>=2
 and exists(select 1 from public.mdm_material where tenant_id=f.tenant_id and inventory_unit_id is not null)
 and exists(select 1 from public.sys_user u where u.tenant_id=f.tenant_id and u.auth_user_id is not null and u.status='1' and not u.user_roles @>array['R_SUPER']) limit 1;
 if actor is null or fund is null then raise exception 'Missing matching fixtures';end if;
 select auth_user_id into ordinary from public.sys_user where tenant_id=tenant and auth_user_id is not null and status='1' and not user_roles @>array['R_SUPER'] limit 1;
 select id,tenant_id into foreign_scheme,foreign_tenant from public.fms_payable_writeoff_scheme where tenant_id<>tenant and automatic and enabled limit 1;
 if ordinary is null or foreign_scheme is null then raise exception 'Missing ordinary and cross-tenant matching fixtures';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.headers','{}',true);
 select id into supplier from public.mdm_supplier where tenant_id=tenant order by id limit 1;
 select id into supplier_two from public.mdm_supplier where tenant_id=tenant and id<>supplier order by id limit 1;
 select id,inventory_unit_id into material,unit_id from public.mdm_material where tenant_id=tenant and inventory_unit_id is not null limit 1;
 select id into finance_type from public.mdm_document_type where tenant_id=tenant and document_type_code='AP_FIN_STANDARD';
 select id into payment_type from public.mdm_document_type where tenant_id=tenant and document_type_code='AP_PAYMENT_PURCHASE';
 select id into purpose from public.mdm_payment_purpose where tenant_id=tenant and code='202';
 select id into method from public.mdm_settlement_method where tenant_id=tenant and code='JSFS04';
 original_rules:='[{"primary_field":"supplier_id","secondary_field":"supplier_id","operator":"eq","empty_matches":false},{"primary_field":"currency_code","secondary_field":"currency_code","operator":"eq","empty_matches":false}]';
 scheme_ident:=public.fms_save_payable_reference_secure('scheme',jsonb_build_object('tenant_id',tenant,'code',code_prefix,'name','自动核销回滚方案','automatic',true,'rules',original_rules));
 manual_scheme:=public.fms_save_payable_reference_secure('scheme',jsonb_build_object('tenant_id',tenant,'code',code_prefix||'_MANUAL','name','异字段匹配回滚方案','automatic',false,'rules','[{"primary_field":"document_no","secondary_field":"source_document_no","operator":"eq","empty_matches":false}]'::jsonb));
 blocked:=false;
 begin perform public.fms_save_payable_reference_secure('scheme',jsonb_build_object('tenant_id',tenant,'code',code_prefix||'_INVALID','name','不兼容规则','rules','[{"primary_field":"amount","secondary_field":"document_no","operator":"gte"}]'::jsonb));exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Incompatible typed rule was accepted';end if;
 if app_private.payable_match_rules(app_private.normalize_payable_match_rules('[{"primary_field":"amount","secondary_field":"amount","operator":"lt"}]'),' {"amount":10}','{"amount":2}') then raise exception 'Numeric comparison used lexical ordering';end if;
 if not app_private.payable_match_rules(app_private.normalize_payable_match_rules('[{"primary_field":"document_no","secondary_field":"source_document_no","operator":"contains"}]'),' {"document_no":"AP-100%"}','{"source_document_no":"100%"}') then raise exception 'Literal text matching failed';end if;
 if app_private.payable_match_rules(app_private.normalize_payable_match_rules('[{"primary_field":"document_no","secondary_field":"source_document_no","operator":"contains"}]'),' {"document_no":"AP-100X"}','{"source_document_no":"100%"}') then raise exception 'Text matching treated literal percent as wildcard';end if;
 for index_value in 1..2 loop
  finance:=public.fms_save_purchase_payable_secure(jsonb_build_object('kind','financial','tenant_id',tenant,'document_type_id',finance_type,'supplier_id',supplier,'business_date',current_date,'lines',jsonb_build_array(jsonb_build_object('material_id',material,'inventory_unit_id',unit_id,'quantity',1,'unit_price',index_value*100,'tax_rate',0))));
  perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'approve');
  payment:=public.fms_save_payable_settlement_secure(jsonb_build_object('kind','payment','tenant_id',tenant,'document_type_id',payment_type,'business_date',current_date,'lines',jsonb_build_array(jsonb_build_object('purpose_id',purpose,'supplier_id',supplier,'settlement_method_id',method,'fund_account_id',fund,'amount',case when index_value=1 then 80 else 220 end))));
  perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'submit');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'approve');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'confirm');
 end loop;
 select count(*) into before_count from public.fms_payable_writeoff_record;
 perform set_config('request.headers',jsonb_build_object('x-art-tenant-scope',tenant)::text,true);
 blocked:=false;begin perform public.fms_auto_payable_writeoff_secure(foreign_scheme,current_date,'{}');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Platform-selected automatic matching crossed tenant scope';end if;
 plan:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier));
 if (plan->>'total_amount')::numeric<>300 or jsonb_array_length(plan->'items')<>3 then raise exception 'Automatic plan did not split both sides in order: %',plan;end if;
 perform set_config('request.headers','{}',true);
 insert into public.sys_role(role_code,role_name,tenant_id,enabled) values(code_prefix||'_ROLE','自动核销安全回归角色',tenant,true) returning id into fixture_role;
 insert into public.sys_role_menu(role_id,menu_id,tenant_id) select fixture_role,id,tenant from public.sys_menu where name='FinancePayableWriteoff:View';
 update public.sys_user set user_roles=array[code_prefix||'_ROLE'] where auth_user_id=ordinary;
 perform set_config('request.jwt.claim.sub',ordinary::text,true);perform set_config('request.headers',jsonb_build_object('x-art-tenant-scope',foreign_tenant)::text,true);
 blocked:=false;begin perform public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,'{}');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'View permission alone permitted automatic matching';end if;
 insert into public.sys_role_menu(role_id,menu_id,tenant_id) select fixture_role,id,tenant from public.sys_menu where name='FinancePayableWriteoff:AutoWriteoff';
 plan:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier));
 if (plan->>'total_amount')::numeric<>300 then raise exception 'Forged header changed ordinary own matching scope';end if;
 blocked:=false;begin perform public.fms_auto_payable_writeoff_secure(foreign_scheme,current_date,'{}');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Ordinary automatic matching accepted foreign scheme';end if;
 if (select count(*) from public.fms_payable_writeoff_record)<>before_count then raise exception 'Preview mutated balances';end if;
 item:=plan->'items'->0;
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.headers','{}',true);
 perform public.fms_payable_writeoff_secure(jsonb_build_array(jsonb_build_object('payable_id',item->>'payable_id','payment_line_id',item->>'payment_line_id','amount',10)),scheme_ident,current_date,'预览后余额变化');
 perform set_config('request.jwt.claim.sub',ordinary::text,true);perform set_config('request.headers',jsonb_build_object('x-art-tenant-scope',foreign_tenant)::text,true);
 blocked:=false;
 begin perform public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier),true,plan->>'plan_token');exception when serialization_failure then blocked:=true;end;
 if not blocked or (select count(*) from public.fms_payable_writeoff_record)<>before_count+1 then raise exception 'Stale plan executed or partially wrote records';end if;
 plan:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier));
 if (plan->>'total_amount')::numeric<>290 then raise exception 'Repreview did not reflect current balances';end if;
 result:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier),true,plan->>'plan_token');
 if not(result->>'executed')::boolean or jsonb_array_length(result->'record_ids')<>jsonb_array_length(plan->'items') then raise exception 'Automatic matching did not persist all previewed rows';end if;
 if exists(select 1 from public.fms_payable_writeoff_record r where r.scheme_id=scheme_ident and match_snapshot='{}') then raise exception 'Rule snapshot not preserved';end if;
 if exists(select 1 from public.fms_payable_writeoff_record r where r.scheme_id=scheme_ident and not r.needs_voucher) then raise exception 'Advance matching lost required accounting documents';end if;
 if exists(select 1 from public.fms_payable_writeoff_record r where r.scheme_id=scheme_ident and r.remark like '按方案自动核销%' and r.actor<>ordinary) then raise exception 'Ordinary automatic writeoff did not preserve actual operator';end if;
 select count(*) into before_count from public.fms_payable_writeoff_record;
 blocked:=false;begin perform public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier),true,plan->>'plan_token');exception when serialization_failure then blocked:=true;end;
 if not blocked or (select count(*) from public.fms_payable_writeoff_record)<>before_count then raise exception 'Repeated confirmation duplicated writeoff';end if;
 plan:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,jsonb_build_object('supplier_id',supplier));
 if jsonb_array_length(plan->'items')<>0 then raise exception 'Fully cleared balances still matched';end if;
 blocked:=false;begin perform public.fms_auto_payable_writeoff_secure(manual_scheme,current_date,'{}');exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Manual-only scheme permitted automatic matching';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.headers','{}',true);
 for index_value in 1..2 loop
  finance:=public.fms_save_purchase_payable_secure(jsonb_build_object('kind','financial','tenant_id',tenant,'document_type_id',finance_type,'supplier_id',case when index_value=1 then supplier else supplier_two end,'business_date',current_date,'lines',jsonb_build_array(jsonb_build_object('material_id',material,'inventory_unit_id',unit_id,'quantity',1,'unit_price',index_value*25,'tax_rate',0))));
  perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'approve');
  payment:=public.fms_save_payable_settlement_secure(jsonb_build_object('kind','payment','tenant_id',tenant,'document_type_id',payment_type,'business_date',current_date,'lines',jsonb_build_array(jsonb_build_object('purpose_id',purpose,'supplier_id',case when index_value=1 then supplier_two else supplier end,'settlement_method_id',method,'fund_account_id',fund,'amount',case when index_value=1 then 50 else 25 end))));
  perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'submit');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'approve');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'confirm');
 end loop;
 plan:=public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,'{}');
 if (plan->>'total_amount')::numeric<>75 or jsonb_array_length(plan->'items')<>2 then raise exception 'Multi-party matching did not respect the scheme';end if;
 if exists(select 1 from jsonb_array_elements(plan->'items') entry join public.fms_purchase_payable_document p on p.id=(entry->>'payable_id')::uuid join public.fms_payable_settlement_line l on l.id=(entry->>'payment_line_id')::uuid where p.supplier_id is distinct from l.supplier_id) then raise exception 'Automatic matching paired different suppliers despite equality rule';end if;
 perform public.fms_auto_payable_writeoff_secure(scheme_ident,current_date,'{}',true,plan->>'plan_token');
 update public.fms_payable_writeoff_scheme set automatic=false where tenant_id=tenant;
 finance:=public.fms_save_purchase_payable_secure(jsonb_build_object('kind','financial','tenant_id',tenant,'document_type_id',finance_type,'supplier_id',supplier,'business_date',current_date,'lines',jsonb_build_array(jsonb_build_object('material_id',material,'inventory_unit_id',unit_id,'quantity',1,'unit_price',40,'tax_rate',0))));
 perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'approve');
 payment:=public.fms_push_payable_settlement_secure((finance->>'id')::uuid,'payment');
 payment:=jsonb_set(payment,'{lines}',jsonb_build_array((payment->'lines'->0)||jsonb_build_object('fund_account_id',fund,'settlement_method_id',method)));
 payment:=public.fms_save_payable_settlement_secure(payment);
 perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'submit');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'approve');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'confirm');
 if not app_private.payable_scheme_matches(manual_scheme,(finance->>'id')::uuid,(payment->'lines'->0->>'id')::uuid) then raise exception 'Primary document number did not match secondary source number';end if;
 perform public.fms_payable_writeoff_secure(jsonb_build_array(jsonb_build_object('payable_id',finance->>'id','payment_line_id',payment->'lines'->0->>'id','amount',40)),manual_scheme,current_date,'主辅不同字段手工核销');
 perform public.fms_save_payable_reference_secure('scheme',jsonb_build_object('id',manual_scheme,'code',code_prefix||'_MANUAL','name','跨单位匹配回滚方案','rules','[{"field":"currency_code","empty_matches":false}]'::jsonb));
 if not exists(select 1 from public.fms_payable_writeoff_scheme where id=manual_scheme and rules->0 ? 'primary_field' and not(rules->0 ? 'field')) then raise exception 'Legacy save did not normalize persisted rules';end if;
 if not exists(select 1 from public.fms_payable_writeoff_record r where r.scheme_id=manual_scheme and r.match_snapshot->'rules'->0->>'primary_field'='document_no') then raise exception 'Scheme edit rewrote historical matching evidence';end if;
 if has_function_privilege('anon','public.fms_auto_payable_writeoff_secure(uuid,date,jsonb,boolean,text)','EXECUTE') then raise exception 'Anonymous automatic writeoff exposed';end if;
end $test$;
rollback;
